export default async function MovedToItems({
  searchParams,
}: { searchParams: Promise<{ type?: string; q?: string }> }) {
  const sp = await searchParams;
  const p = new URLSearchParams();
  if (sp.type && sp.type !== 'FIN') p.set('type', sp.type);
  else p.set('group', 'material');
  if (sp.q) p.set('q', sp.q);
  redirect(`/settings/items?${p}`);
}

